"""Persist generated bytes: R2 when configured, otherwise local files served by /api/media."""

from __future__ import annotations

import logging
from collections.abc import Sequence
from pathlib import Path

from redis.asyncio import Redis

from app.adobe.client import GeneratedImage
from app.core.crypto import FieldCipher
from app.services.config.r2 import R2UsageService, upload_object
from app.services.config.schema import R2Account, SystemConfig

logger = logging.getLogger(__name__)

RR_KEY = "firefly:r2:rr"


def _extension(content_type: str) -> str:
    lowered = content_type.lower()
    if "jpeg" in lowered or "jpg" in lowered:
        return "jpg"
    if "webp" in lowered:
        return "webp"
    if "mp4" in lowered:
        return "mp4"
    return "png"


def object_key(prefix: str, *, job_id: str, suffix: str) -> str:
    rest = f"jobs/{job_id}/0.{suffix}"
    cleaned = prefix.strip().strip("/")
    return f"{cleaned}/{rest}" if cleaned else rest


def ready_accounts(cfg: SystemConfig) -> list[R2Account]:
    return [
        account
        for account in cfg.r2_accounts
        if account.enabled and account.access_key_id and account.secret_key_enc
    ]


def round_robin_order(accounts: Sequence[R2Account], start: int) -> list[R2Account]:
    if not accounts:
        return []
    index = start % len(accounts)
    return list(accounts[index:]) + list(accounts[:index])


async def _rr_start(redis: Redis | None, n: int) -> int:
    if redis is None or n <= 0:
        return 0
    try:
        return (int(await redis.incr(RR_KEY)) - 1) % n
    except Exception:  # noqa: BLE001 - counter is best-effort
        logger.debug("r2 round-robin counter failed", exc_info=True)
        return 0


def _write_local(job_id: str, image: GeneratedImage, media_dir: Path, suffix: str) -> str:
    folder = media_dir / job_id
    folder.mkdir(parents=True, exist_ok=True)
    (folder / f"0.{suffix}").write_bytes(image.content)
    (folder / "0.ctype").write_text(image.content_type or "image/png", encoding="utf-8")
    return f"/api/media/{job_id}/0"


async def store_image(
    *,
    job_id: str,
    image: GeneratedImage,
    cfg: SystemConfig,
    cipher: FieldCipher,
    media_dir: Path,
    redis: Redis | None = None,
) -> str:
    suffix = _extension(image.content_type)
    candidates = ready_accounts(cfg)
    ordered = round_robin_order(candidates, await _rr_start(redis, len(candidates)))
    usage = R2UsageService(redis) if redis is not None else None
    for account in ordered:
        secret = cipher.decrypt(account.secret_key_enc)
        if usage is not None:
            snapshot = await usage.usage(account, secret)
            if snapshot.over_quota:
                logger.info("r2 skip over_quota", extra={"r2_id": account.id})
                continue
        key = object_key(account.prefix, job_id=job_id, suffix=suffix)
        try:
            url = await upload_object(
                account,
                secret,
                key=key,
                body=image.content,
                content_type=image.content_type or "image/png",
            )
        except Exception:  # noqa: BLE001 - try the next account
            logger.warning(
                "r2 upload failed, trying next", extra={"r2_id": account.id}, exc_info=True
            )
            continue
        if url.startswith("http"):
            return url
        if account.public_base_url:
            return f"{account.public_base_url.rstrip('/')}/{key}"
        return url
    return _write_local(job_id, image, media_dir, suffix)
